{% macro input(field, value) %}
<div class="mb-4">
    <label class="block text-sm font-medium text-gray-700 mb-1.5">{{ field.label }}</label>
    {% if field.type == 'textarea' %}
    <textarea name="{{ field.name }}" rows="3" class="w-full bg-white border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-green-500 focus:border-green-500 p-2.5">{{ value }}</textarea>
    {% elseif field.type == 'select' %}
    <select name="{{ field.name }}" class="data-choices w-full bg-white border border-gray-300 text-gray-900 text-sm rounded-lg p-2.5">
        {% for opt in field.options %}
        <option value="{{ opt.value }}"{{ opt.value == value ? ' selected' : '' }}>{{ opt.label }}</option>
        {% endfor %}
    </select>
    {% elseif field.type == 'date' %}
    <input type="text" name="{{ field.name }}" value="{{ value }}" class="datepicker w-full bg-white border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-green-500 focus:border-green-500 p-2.5">
    {% elseif field.type == 'checkbox' %}
    <input type="checkbox" name="{{ field.name }}" value="1"{{ value ? ' checked' : '' }} class="w-4 h-4 text-green-800 border-gray-300 rounded focus:ring-green-500">
    {% elseif field.type == 'number' %}
    <input type="number" name="{{ field.name }}" value="{{ value }}" step="any" class="w-full bg-white border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-green-500 focus:border-green-500 p-2.5">
    {% elseif field.type == 'password' %}
    <input type="password" name="{{ field.name }}" autocomplete="new-password" class="w-full bg-white border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-green-500 focus:border-green-500 p-2.5">
    {% else %}
    <input type="text" name="{{ field.name }}" value="{{ value }}" class="w-full bg-white border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-green-500 focus:border-green-500 p-2.5">
    {% endif %}
</div>
{% endmacro %}

