public function editPermissions(Request $request, Response $response, array $args): Response
{
    $role = Role::findOrFail((int) $args['id']);
    $grouped = Permission::orderBy('module')->get()->groupBy('module');
    $rolePermissionIds = $role->permissions()->pluck('permissions.id')->all();

    $view = Twig::fromRequest($request);
    return $view->render($response, 'roles/permissions.twig', [
        'role' => $role,
        'grouped_permissions' => $grouped,
        'role_permission_ids' => $rolePermissionIds,
    ]);
}

public function updatePermissions(Request $request, Response $response, array $args): Response
{
    $role = Role::findOrFail((int) $args['id']);
    $data = (array) $request->getParsedBody();
    $permissionIds = array_map('intval', $data['permission_ids'] ?? []);

    $role->permissions()->sync($permissionIds);
    $this->auditService->log(null, 'update_permissions', 'roles', "Permissions updated for role '{$role->name}'", null, null);

    return $response->withHeader('Location', '/roles')->withStatus(302);
}

